function main(): void {
  const fs: (() => number)[] = [];
  let acc = 0;
  for (let i = 0; i < 5; i++) {
    const s = "abc" + i;
    const k = Math.imul(i + 1, 31) + s.charCodeAt(2) + s.length;
    acc += k;
    fs.push(() => k + s.charCodeAt(3));
  }
  console.log(acc, fs.map((f) => f()).join(","));
  const t = (x: string) => x.charCodeAt(0) + x.charCodeAt(5) + x.length;
  console.log(t("ab"), t("abcdefg"));
  let h = 0;
  const words = ["alpha", "beta", "gamma"];
  for (const w of words) for (let k = 0; k < w.length; k++) h = (Math.imul(h, 31) + w.charCodeAt(k)) | 0;
  console.log(h);
  try {
    const bad: any = null;
    console.log(Math.imul(1, 2) + bad.x.charCodeAt(0));
  } catch (e: any) {
    console.log("caught", e instanceof TypeError);
  }
}
